const TIERS = [
  { maxG: 500, cents: 490 },
  { maxG: 2000, cents: 790 },
  { maxG: 10000, cents: 1290 },
];
const OVERSIZE_CENTS = 1990;
const FREE_FROM_CENTS = 10000;

function shippingCents(weightG) {
  for (const t of TIERS) {
    if (weightG <= t.maxG) return t.cents;
  }
