import calendar
from datetime import date, timedelta


def add_months(d, n):
    total = d.year * 12 + (d.month - 1) + n
    year, month0 = divmod(total, 12)
    month = month0 + 1
    day = min(d.day, calendar.monthrange(year, month)[1])
    return date(year, month, day)


def renewal_dates(start, every_months, count):
    return [add_months(start, every_months * k) for k in range(1, count + 1)]


def nights(checkin, checkout):
    if checkout <= checkin:
        raise ValueError("checkout must be after checkin")
    return (checkout - checkin).days


def overlaps(a, b):
    a0, a1 = a
    b0, b1 = b
    return a0 < a1 and b0 < b1 and a0 < b1 and b0 < a1


def iso_week_label(d):
    year, week, _ = d.isocalendar()
    return f"{year}-W{week:02d}"


def business_days(start, end, holidays=()):
    holiday_set = set(holidays)
    count = 0
    d = start
    while d < end:
        if d.weekday() < 5 and d not in holiday_set:
            count += 1
        d += timedelta(days=1)
    return count


def age_on(birth, on):
    if on < birth:
        raise ValueError("date before birth")
    birthday = birth.replace(year=on.year)
    return on.year - birth.year - (1 if on < birthday else 0)

