	got := f.Push(Event{Seq: 1, SKU: "x", Kind: Receive, Qty: 1})
	if len(got) != 3 || got[0] != 1 || got[2] != 3 || f.State().Stock["x"] != 3 || f.Pending() != 0 {
		t.Fatalf("got %v stock %v pending %d", got, f.State().Stock, f.Pending())
